import type { HTMLAttributes, LiHTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";

/** Rows separated by hairlines: upcoming appointments, recent activity, needs-attention. */
export function DataList({ className, ...rest }: HTMLAttributes<HTMLUListElement>) {
  return <ul {...rest} className={cx("hm-data-list", className)} />;
}

export type DataListItemProps = LiHTMLAttributes<HTMLLIElement> & {
  /** Secondary line under the primary content. */
  description?: ReactNode;
  /** Right-aligned meta: a time, an amount, a status. */
  meta?: ReactNode;
  /** Row actions, revealed on hover/focus with a fine pointer, always visible on touch. */
  actions?: ReactNode;
};

export function DataListItem({ description, meta, actions, className, children, ...rest }: DataListItemProps) {
  return (
    <li {...rest} className={cx("hm-data-list-item", className)}>
      <span className="hm-data-list-main">
        {children}
        {description ? <small className="hm-data-list-description">{description}</small> : null}
      </span>
      {meta ? <span className="hm-data-list-meta">{meta}</span> : null}
      {actions ? <span className="hm-data-list-actions">{actions}</span> : null}
    </li>
  );
}

/** A centered, quiet message for an empty list or section. */
export function EmptyState({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-empty", className)} />;
}
